-- =====================================================================
-- STEP 6  タグ付けの結果（スプシの raw タブ）を DB に入れる
--   元：Giftia スプレッドシート raw タブ（誕生日タグ 4,649件のうちタグのある商品）
--   スプシの「|」区切りを 1タグ＝1行 に分け、名前を番号に置き換え済み
--     ・見た目「すっきり系」は「シンプル系」（V02）として入れる
--     ・「香りを楽しむ（…）」のようなかっこ書きは外して、一覧の名前に合わせた
--   product_taste_groups 9512行 / product_tastes 5229行
--   上から全部まとめて実行してよい。何度実行しても、同じ行が二重に入ることはない
-- =====================================================================

-- 6-1  いったん置き場（作業用の表）に入れる
DROP TABLE IF EXISTS stg_product_taste_groups;
DROP TABLE IF EXISTS stg_product_tastes;
CREATE TABLE stg_product_taste_groups (product_id VARCHAR(10) NOT NULL, group_id VARCHAR(10) NOT NULL, PRIMARY KEY (product_id, group_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;
CREATE TABLE stg_product_tastes (product_id VARCHAR(10) NOT NULL, taste_id VARCHAR(10) NOT NULL, PRIMARY KEY (product_id, taste_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;
