-- 6-2  本番の表に入れる
--   系統：商品と系統が DB にあるものだけ
INSERT IGNORE INTO product_taste_groups (product_id, group_id)
SELECT s.product_id, s.group_id
FROM stg_product_taste_groups s
JOIN products p ON p.product_id = s.product_id
JOIN taste_groups g ON g.group_id = s.group_id;

--   テイスト：商品のカテゴリーとテイストのカテゴリーが同じものだけ（ER図※1）
INSERT IGNORE INTO product_tastes (product_id, taste_id)
SELECT s.product_id, s.taste_id
FROM stg_product_tastes s
JOIN products p ON p.product_id = s.product_id
JOIN tastes t ON t.taste_id = s.taste_id AND t.category_id = p.category_id;

-- 6-3  確認：入らなかった行の数（どちらも 0 ならOK）
SELECT '系統で入らなかった行' AS 確認, COUNT(*) AS 件数
FROM stg_product_taste_groups s
LEFT JOIN product_taste_groups x ON x.product_id = s.product_id AND x.group_id = s.group_id
WHERE x.product_id IS NULL
UNION ALL
SELECT 'テイストで入らなかった行', COUNT(*)
FROM stg_product_tastes s
LEFT JOIN product_tastes x ON x.product_id = s.product_id AND x.taste_id = s.taste_id
WHERE x.product_id IS NULL
UNION ALL
SELECT 'product_taste_groups の行数', COUNT(*) FROM product_taste_groups
UNION ALL
SELECT 'product_tastes の行数', COUNT(*) FROM product_tastes;

